using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Transport;

internal sealed class MatrixUnitDysonDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The actual noncommutative Dyson series constructs the unique solution and transports every moving logical matrix unit on a finite closed interval.",
        H("Constructive transport of moving logical matrix units"),
        Blocks(Describe.Lean(
            DescribeId.Create("constructive-transport"),
            DeclarationHandle.Create("D5/S3/Quantum/Transport/MatrixUnitDyson.constructive_transport"),
            H("Ordered integrals and complete unitary transport"),
            StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(
                LibraryNoteRef.Create("D5/L/Analytic/baake2011peanobaker"),
                LibraryNoteRef.Create("D5/L/Dynamics/dyson1949radiation"),
                LibraryNoteRef.Create("D5/L/Quantum/kato1950adiabatic")),
            Blocks(
                Paragraph(Text("For every continuous matrix path K on [0,T] with T nonnegative, the recursive Bochner integral orderedTerm equals the independently defined closed-simplex integral simplexTerm. The simplex product is List.ofFn followed by List.prod in decreasing time order, so no commutation is imposed. Each nonnegative uniform bound M gives the estimate (Mt)^m/m!, including m=0 and T=0.")),
                Paragraph(Text("The series dysonSeries is the actual sum of these recursive terms. It converges absolutely at each point and uniformly on the closed interval, is continuous, solves G(t)=I+integral from 0 to t of K(s)G(s), has within derivative K(t)G(t) at every point including both endpoints, and satisfies G(0)=I. Every continuous solution of that integral equation agrees with G.")),
                Paragraph(Text("For a positive-length interval, finite logical indices d with d nonempty, and finite physical indices n, continuous F and D with the stated entrywise within derivatives and finite-interval matrix-unit multiplication and adjoint laws give the computed generator K=averagedVelocity(F,D)-unitSupport(F) supportVelocity(D). Its skew-adjointness, all matrix-unit and support commutators, the one-logical-index projector formula, and all analytic series clauses are conclusions. G is unitary on both sides, the transported logical matrix units have zero within derivative, and F(t)=G(t)F(0) times the conjugate transpose of G(t). The physical type n may be empty.")),
                Paragraph(Text("The Peano-Baker and Dyson constructions and projector parallel transport are classical. This declaration assembles their finite-interval realization with the repository's computed full matrix-unit generator; it claims no mathematical priority. The result concerns finite complex matrices and one time interval. It supplies neither a parameter-bundle trivialization nor a physical control-cost or adiabatic-error estimate.")),
                Paragraph(Text("All-time continuous-field application (V82 Theorem 7.2 and V83 Theorem 11.2). Fix one finite-dimensional complex Hilbert carrier H and one finite complex orthonormal basis a, including the empty basis. The actual field v_t is defined on the entire unit sphere. Relative to the same coherent reference, its assumptions are Re(inner(x,v_t(x)))=0, 2 Re(inner(x-y,v_t(x)-v_t(y)))<=0 for every pair of unit inputs, and v_t(i a_j)=i v_t(a_j). Only the finitely many functions t -> v_t(a_j) are required to be continuous; continuity or linearity of the actual sphere field is not an input. Expanding the pair inequality gives B_t(x,y)=Re(inner(x,v_t(y)))+Re(inner(y,v_t(x)))>=0. Testing opposite inputs and the anchors a_j,i a_j forces v_t(-y)=-v_t(y), then B_t=0. The two calibrated anchor pairings give inner(a_j,v_t(x))=-inner(v_t(a_j),x). With L_t=a.toBasis.constr(complex scalars,j -> v_t(a_j)), the adjoint identities and basis extensionality give v_t(x)=-L_t† x and L_t=-L_t†. Thus the actual extension is K(t)=L_t, not a separately assumed linear field. Its finite rank-one formula K(t)x=sum_j inner(a_j,x) v_t(a_j) proves continuity from precisely the stated anchor data.")),
                Paragraph(Text("For arbitrary continuous K on the whole real line, the first, generic branch of constructive_transport supplies the same literal dysonSeries(K) on every [0,T], rather than a family of independently chosen local solutions. Put P=dysonSeries(K), N=dysonSeries(t -> -K(-t)), and G(t)=P(t) for t>=0 and N(-t) for t<0. For each nonnegative t choose a horizon T>t and restrict the supplied within derivative to the positive half-line. Reflection gives the negative-time derivative. P(0)=N(0)=I and the matching one-sided derivatives combine by HasDerivWithinAt.union, yielding G'=KG at every real time. LinearMap.toMatrixOrthonormal and the finite-dimensional continuous-linear-map equivalence transfer this formula to H. This application does not construct a new infinite extension: the frozen ordered series already supplies the infinite analytic construction, and its horizon-independent formula supplies compatibility. No uniform global coefficient bound, uniform global time step, commutation or time derivative of K is required.")),
                Paragraph(Text("When K(t)†=-K(t), differentiating G(t)†G(t) and using its initial value gives G†G=I; finite-dimensional left/right inverse equivalence gives GG†=I. The literal propagator U(t,s)=G(t)G(s)† therefore has U(s,s)=I, first-time derivative K(t)U(t,s), both unitary inverse equations, and U(t,s)U(s,r)=U(t,r) for all real t,s,r. For uniqueness between any two times, take one compact interval containing both and use its own coefficient bound with ODE_solution_unique_of_mem_Ioo; no bound outside that interval enters. Evaluation at an actual unit input gives a sphere curve with derivative v_t(U(t,s)x). Each sphere map has antipodal image closure A by choosing -x, chord nonexpansion N by its linear-isometry norm identity, and the finite calibration J by complex linearity; in fact all complex inner products are preserved. The same finite carrier includes all retained return records, with one common reference. Cross-carrier identifications or omission of records are not supplied by this argument. A concrete coefficient path is K(t)=i(X+tZ) for the two Pauli matrices: K(0) and K(1) do not commute, and its norm is unbounded in time. No exponential of an integrated noncommuting coefficient is used.")),
                Paragraph(Text("For the converse applied to an actual finite V83 gate F:S(H)->S(H), retain its original A/N/J hypotheses: the image is antipodally closed, every chord is nonexpanding, and F(i a_j)=i F(a_j) at the finite anchors. No continuity, linearity, isometry or surjectivity of F is assumed. A preimage of -F(x), together with N, attains the sphere diameter; the parallelogram identity forces that preimage to be -x. Thus F is odd. Applying N to y and -y and expanding the squared norms forces preservation of the real inner pairing. Pairing with a_j and i a_j and using J recovers the complete complex anchor coordinates. The original Basis.constr, LinearMap.isometryOfOrthonormal and LinearIsometry.toLinearIsometryEquiv suppliers give a unitary u; coordinates in the mapped orthonormal basis identify the actual F(x) with u x on the whole sphere. This parameter correspondence includes the empty sphere and uses the same complete finite carrier and coherent reference. The finite-unitary logarithm construction then realizes this very actual gate.")),
                Paragraph(Text("Conversely, a finite unitary operator u has finite spectrum by Module.End.finite_spectrum and the continuous-linear-map algebra equivalence. On this finite set the complex argument is continuous, even if the spectrum contains -1. Apply Unitary.argSelfAdjoint and continuous functional calculus to obtain the self-adjoint a with exp(i a)=u, and put K=i a. The original exponential/skew-adjoint and derivative suppliers give K†=-K, a smooth real-time curve exp(t K), its derivative K exp(t K), and unitary values for every real t. The linear field x -> Kx satisfies tangency, zero binary separation rate and finite complex calibration directly by the adjoint identity, so this is a smooth skew-tangent realization of the specified finite unitary. The empty-carrier case is included throughout. The logarithm and intervening history need not be unique, the time-dependent propagator need not be an autonomous group, and the realization need not belong to a restricted native gate menu. These are mathematical applications of the cited frozen and upstream suppliers, not additional mathematical declarations, empirical calibration claims or a new priority claim.")),
                Paragraph(Text("ST40.1 application data and constructions. Let F and D be the actual matrix-unit path and its tangent, let P(t)=unitSupport(F t), and compute K(t)=transportGenerator(F t,D t). The logical index type d is finite and nonempty; the physical index type n is finite and may be empty. On [0,T], T>=0, F and D are continuous, D is the entrywise within derivative of F, and the matrix-unit multiplication and adjoint laws hold on the interval. For T>0 these are precisely the interval hypotheses of constructive_transport; no off-interval law is required. When T=0, the actual ambient path supplies the entrywise derivative D(0) and the matrix-unit and adjoint laws near 0. Differentiating those nearby laws supplies the zero-duration tangent identities; a derivative within a singleton is not used to identify a tangent. Given continuous Hermitian hL and hbar>0, Delta>0, put c=-i/hbar, G=dysonSeries(K), and VL=dysonSeries(c hL). The generic ordered-series branch of constructive_transport gives the continuity, initial value and within derivative of these particular series. The skew-adjointness of c hL and differentiation of VL†VL give VL†VL=VL VL†=I; the singleton case follows directly from VL(0)=I.")),
                Paragraph(Text("The representation is the literal finite sum pi_t(A)=representedMatrix(F t,A)=sum over i,j of A_ij F_ij(t). The existing represented_matrix_mul theorem gives pi_t(A)pi_t(C)=pi_t(AC); exchanging the two finite indices gives pi_t(A)†=pi_t(A†), and the diagonal sum gives pi_t(I)=P(t). Consequently P pi_t(A)=pi_t(A)P=pi_t(A), P†=P and P^2=P. The differentiated matrix-unit laws instantiate matrix_unit_transport_generator, so K†=-K even for a zero-duration interval. Therefore the actual Hphys(t)=i hbar K(t)+pi_t(hL(t))+Delta(I-P(t)) is continuous and Hermitian. No physical propagator or covariance identity is assumed in this construction.")),
                Paragraph(Text("For T>0, constructive_transport supplies both inverse equations for this G and the transported-unit equality F_ij(t)=G(t)F_ij(0)G(t)†. For T=0 these equalities are the initial identities. Summing the transported units and using G†G=I yields pi_t(A)G(t)=G(t)pi_0(A), including P(t)G(t)=G(t)P(0). Write Q0=I-P(0), z(t)=exp((-i/hbar)Delta t), B(t)=pi_0(VL(t))+z(t)Q0 and V(t)=G(t)B(t). The support relations give Q0^2=Q0 and kill both mixed products. Since conjugate(z)z=1 and pi_0(VL)†pi_0(VL)=P(0), B†B=BB†=I; the inverse equations for G then give V†V=VV†=I. The literal formulas also give B(0)=V(0)=I.")),
                Paragraph(Text("The finite-sum linear map pi_0 carries the logical derivative to the represented derivative. Together with z'=c Delta z and the support identities, this gives B'=c[pi_0(hL)+Delta Q0]B. Differentiating the literal product V=GB, using G'=KG and the already derived covariance, gives V'=c Hphys V, equivalently i hbar V'=Hphys V. These are within derivatives on the closed interval, with the usual derivative on its interior. Continuity and the fundamental theorem of calculus give V(t)=I+integral from 0 to t of (c Hphys(s))V(s); the uniqueness clause of constructive_transport for the continuous generator c Hphys then identifies this very V with dysonSeries(c Hphys). At T=0 the integral is zero and the initial identities settle uniqueness, without a singleton derivative-uniqueness inference. This is an active-control mathematical realization and supplies no control-bandwidth, energy-budget, locality or adiabatic-error estimate. The same-channel recovery identity and the closed-loop tensor consequences require their own subsequent applications."))),
            DescribeRole.Theorem))));
}
